/// Light is paper and ink, Dark ink and paper: flat, square, hairlines; the highlighters mark
/// what is selected, the stamp rose what is active. The area behind pages stays neutral grey.
pub fn tokens(t: Tokens) -> Tokens {
    match t.kind {
        ThemeKind::Light => {
            let ink = |x: f32| mix(PAPER, BLACK, x);
            Tokens {
                titlebar: ink(0.08),
                chrome: PAPER,
                panel: PAPER,
                card: PAPER,
                border: ink(0.25),
                divider: ink(0.14),
                text: BLACK,
                text_muted: ink(0.70),
                text_faint: ink(0.58),
                icon: BLACK,
                hover: ink(0.07),
                pressed: ink(0.14),
                selected: mix(PAPER, YELLOW, 0.55),
                accent: ROSE,
                accent_text: ROSE,
                accent_soft: mix(PAPER, YELLOW, 0.45),
                field: WHITE,
                badge_new: ROSE,
                radius: {{shape.radius_sm}},
                ..t
            }
        }
        ThemeKind::Dark => {
            let ink = |x: f32| mix(BLACK, PAPER, x);
            Tokens {
                titlebar: mix(BLACK, Color32::BLACK, 0.30),
                chrome: BLACK,
                panel: BLACK,
                card: mix(BLACK, PAPER, 0.05),
                border: ink(0.24),
                divider: ink(0.15),
                text: PAPER,
                text_muted: ink(0.72),
                text_faint: ink(0.60),
                icon: ink(0.88),
                hover: ink(0.10),
                pressed: ink(0.18),
                selected: mix(BLACK, ROSE, 0.45),
                accent: PINK,
                accent_text: PINK,
                accent_soft: mix(BLACK, ROSE, 0.35),
                field: mix(BLACK, Color32::BLACK, 0.30),
                badge_new: ROSE,
                radius: {{shape.radius_sm}},
                ..t
            }
        }
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.menu_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.window_shadow = egui::Shadow::NONE;
    v.popup_shadow = egui::Shadow::NONE;
}

/// An RGBA PNG (8 bits per channel) as a mipmapped texture, decoded once per context.
fn png_texture(ctx: &Context, name: &str, bytes: &[u8]) -> Option<TextureHandle> {
    let id = Id::new(name);
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(png::Transformations::EXPAND);
    let mut reader = decoder.read_info().ok()?;
    let mut buf = vec![0; reader.output_buffer_size()?];
    let info = reader.next_frame(&mut buf).ok()?;
    if info.color_type != png::ColorType::Rgba || info.bit_depth != png::BitDepth::Eight {
        return None;
    }
    buf.truncate(info.buffer_size());
    let image = egui::ColorImage::from_rgba_unmultiplied([info.width as usize, info.height as usize], &buf);
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture(name, image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

const MARK_PNG: &[u8] = include_bytes!("../../../assets/app-icon/{{this.repo}}-mark.png");
const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

/// This app's mark (its monogram tile), `size` points square.
pub fn mark(ui: &mut Ui, size: f32) -> Response {
    match png_texture(ui.ctx(), "freeandiy-mark", MARK_PNG) {
        Some(tex) => ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(size, size)).alt_text("{{brand.name}}")),
        None => ui.allocate_response(egui::vec2(size, size), egui::Sense::hover()),
    }
}

/// The FreeANDIY wordmark: the name set in IBM Plex Mono, `height` points tall.
pub fn logo(ui: &mut Ui, height: f32) -> Response {
    let t = Tokens::get(ui.ctx());
    ui.add(egui::Label::new(egui::RichText::new("{{brand.name}}").monospace().size(height).strong().color(t.text)))
}

const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

/// The About tab's attribution: the Free Andy Agency seal and the upstream credit (MIT/Apache-2.0
/// require keeping the notices; the ArtCraft brand terms allow naming the origin in plain text).
pub fn about_attribution(ui: &mut Ui) {
    let tk = Tokens::get(ui.ctx());
    ui.horizontal(|ui| {
        if let Some(tex) = png_texture(ui.ctx(), "freeandiy-seal", SEAL_PNG) {
            ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(48.0, 48.0)));
        }
        ui.vertical(|ui| {
            let attribution = crate::i18n::fmt(t(ATTRIBUTION), &[("app", APP_NAME), ("upstream", UPSTREAM_NAME)]);
            ui.label(egui::RichText::new(attribution).small().color(tk.text_muted));
            ui.label(egui::RichText::new(format!("© {OWNER}")).small().color(tk.text_muted));
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_marks_decode() {
        let ctx = Context::default();
        assert!(png_texture(&ctx, "seal", SEAL_PNG).is_some());
        assert!(png_texture(&ctx, "mark", MARK_PNG).is_some());
    }

    #[test]
    fn both_themes_are_paper_and_ink() {
        let light = Tokens::for_kind(ThemeKind::Light);
        let dark = Tokens::for_kind(ThemeKind::Dark);
        assert_eq!((light.panel, light.text, light.accent), (PAPER, BLACK, ROSE));
        assert_eq!((dark.panel, dark.text), (BLACK, PAPER));
        assert!(light.radius <= 4 && dark.radius <= 4);
    }
}
